package io.github.eschizoid.telescope.conversion;

import io.github.eschizoid.telescope.internal.FixedCheck;

/**
 * The check a conversion makes of a value handed across unchanged into a property whose class fixes
 * the type variable the property is declared with, where the other side passes that variable
 * through. {@code Telescope.mapper(...)} makes it for such a property, and a bridge generated by
 * {@code @Bridge} calls it where it casts the value to the fixed class, so the two paths refuse the
 * same value in the same words.
 *
 * <p>Public so generated code in any package can call it; not meant to be called directly.
 */
public final class FixedClass {

  private FixedClass() {}

  /**
   * {@code value} itself, when it is null or an instance of {@code fixed}.
   *
   * @param value the value handed across
   * @param fixed the class the receiving side fixes the variable to
   * @param owner the class whose property is written
   * @param property the name of the property written
   * @param <V> the type the value is held as
   * @return {@code value}
   * @throws ClassCastException naming the property, the value's class and {@code fixed} when the
   *     value is of another class
   */
  public static <V> V checked(final V value, final Class<?> fixed, final Class<?> owner, final String property) {
    return FixedCheck.checked(value, fixed, owner, property);
  }
}
